import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Equazioni logaritmiche","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/a_algebra/al/alj.md","filePath":"lezioni/a_algebra/al/alj.md"}`),a={name:`lezioni/a_algebra/al/alj.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="equazioni-logaritmiche" tabindex="-1">Equazioni logaritmiche <a class="header-anchor" href="#equazioni-logaritmiche" aria-label="Permalink to “Equazioni logaritmiche”">​</a></h1><p>Sono equazioni in cui la <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi></mrow><annotation encoding="application/x-tex">x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span> compare nell&#39;argomento del logaritmo;</p><p>Per risolverle si cerca di ottenere un solo logaritmo sia prima che dopo l&#39;uguale in modo da poter uguagliare gli argomenti; però, uguagliando gli argomenti si potrebbero aggiungere soluzioni non possibili: infatti l&#39;argomento del logaritmo deve sempre essere maggiore di zero.</p><p>Per risolvere il problema esistono due metodi:</p><ul><li><strong>Primo metodo:</strong> prima di iniziare a risolvere le equazioni si fa un sistema ponendo tutti gli argomenti maggiori di zero, si risolve il sistema e si trova l&#39;intervallo in cui le soluzioni sono valide. Successivamente si va a risolvere l&#39;equazione logaritmica e, una volta trovate le soluzioni, si controlla che cadano entro l&#39;intervallo di validità.</li><li><strong>Secondo metodo:</strong> si risolve l&#39;equazione e quindi si sostituiscono le soluzioni una alla volta nell&#39;equazione iniziale per controllare se i logaritmi sono validi.</li></ul><p>Il secondo metodo è forse più semplice ed intuitivo, ma il primo metodo ti predispone il discorso sulla risoluzione delle disequazioni logaritmiche.</p><hr><p>Vediamo nella prossima pagina alcuni <a href="./alja.html">esercizi</a></p>`,8)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};